    private async Task HandleLogin()
    {
        isLoading = true;
        errorMessage = null;
        successMessage = null;

        try
        {
            var response = await AuthService.LoginAsync(loginModel);
            switch (response.StatusCode)
            {
                case 401:
                    errorMessage = response.Message;
                    break;

                case 423:
                    errorMessage = response.Message;
                    break;

                case 400:
                    errorMessage = response.Message;
                    break;

                case 500:
                    errorMessage = "An unexpected server error occurred.";
                    break;

                default:
                    await TokenServices.SaveToken(response.Data!.accessToken);
                    await AuthStateProvider.NotifyUserAuthentication(response.Data.accessToken);
            
                    successMessage = "Login successful!";
                    StateHasChanged();
                    await Task.Delay(800);
                    Navigation.NavigateTo("/dashboard"); 
                    break;
            }
            
        }
        catch
        {
           errorMessage = "Server error. Try again later.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void ShowSuccess(string message)
    {
        successMessage = message;
        errorMessage = null;
    }

    private void ShowError(string message)
    {
        errorMessage = message;
        successMessage = null;
    }
    private async Task AutoClear()
    {
        await Task.Delay(3000);
        errorMessage = null;
        successMessage = null;
        StateHasChanged();
    }

